parameters.jsCode:
const payload = typeof $input.item.json.body === 'string'
  ? JSON.parse($input.item.json.body)
  : $input.item.json;

if (!payload.violation_id) {
  throw new Error('Missing required field: violation_id');
}

return [{
  json: {
    violation_id: payload.violation_id,
    facility_id: payload.facility_id,
    equipment_id: payload.equipment_id || null,
    severity: payload.severity || 'unknown',
    violation_type: payload.violation_type || 'unknown',
    regulation_code: payload.regulation_code || '',
    description: payload.description || '',
    detected_at: payload.detected_at || new Date().toISOString(),
    is_critical: payload.severity === 'critical'
  }
}];

